const SELECTOR=Symbol.for(`eve.sandbox-selector`),PARENT=Symbol.for(`eve.sandbox-parent-definition`);function defineSandbox(e){return Object.defineProperty(e,SELECTOR,{value:!0}),e}function defineParentSandbox(){let e=defineSandbox(async()=>{throw Error(`Parent sandbox selection is resolved by eve.`)});return Object.defineProperty(e,PARENT,{value:!0}),e}export{defineParentSandbox,defineSandbox};